//! Delivery range evidence at distinct pipeline stages, not broadcast certification.
use crate::{effects::Frame,model::Project};use serde_json::{json,Value};
fn range(f:&Frame)->Value{let(mut invalid,mut transparent,mut below,mut above,mut negative_alpha,mut high_alpha)=(0u64,0u64,[0u64;3],[0u64;3],0u64,0u64);let mut lo=[f64::INFINITY;3];let mut hi=[f64::NEG_INFINITY;3];let mut n=0u64;for p in f.d.chunks_exact(4){if p.iter().any(|v|!v.is_finite()){invalid+=1;continue}if p[3]<0.{negative_alpha+=1}if p[3]>1.{high_alpha+=1}if p[3]<=0.{transparent+=1;continue}n+=1;for j in 0..3{let v=p[j] as f64;lo[j]=lo[j].min(v);hi[j]=hi[j].max(v);if v<0.{below[j]+=1}if v>1.{above[j]+=1}}}json!({"visible_pixels":n,"nonfinite_pixels":invalid,"transparent_or_nonpositive_alpha_pixels":transparent,"negative_alpha_pixels":negative_alpha,"above_one_alpha_pixels":high_alpha,"min_rgb":if n>0{Some(lo)}else{None},"max_rgb":if n>0{Some(hi)}else{None},"below_zero_rgb":below,"above_one_rgb":above})}
pub fn audit(p:&Project,f:&Frame)->Result<Value,String>{let q=&p.color_pipeline;if !q.enabled{return Err("output audit requires managed working-linear project".into())}q.validate()?;if f.w.checked_mul(f.h).and_then(|n|n.checked_mul(4))!=Some(f.d.len()){return Err("invalid audit frame".into())}let mut params=crate::effects::Params::new();for(k,v)in[("from_gamut",q.working_gamut as f64),("to_gamut",q.output_gamut as f64),("from_transfer",0.),("to_transfer",0.),("reference_white",q.reference_white)]{params.insert(k.into(),crate::keyframe::Prop::new(v));}let working=range(f);let mut output=Frame{w:f.w,h:f.h,d:f.d.clone()};super::managed::apply(&params,&mut output,0.)?;let linear=range(&output);let peak=if q.output_transfer==6{Some(10000./q.reference_white)}else{None};let pq_over=peak.map(|peak|output.d.chunks_exact(4).filter(|p|p[3]>0.&&p[..3].iter().any(|v|*v as f64>peak)).count());output.d.copy_from_slice(&f.d);super::pipeline::output(p,&mut output)?;let encoded=range(&output);Ok(json!({"working_linear":working,"output_gamut_linear_before_mapping":linear,"configured_encoded_output":encoded,"output_gamut":q.output_gamut,"output_transfer":q.output_transfer,"tone_map_enabled":q.tone_map,"gamut_compress_enabled":q.gamut_compress,"pq_nominal_peak_linear":peak,"above_pq10000nit_rgb_pixels_before_mapping":pq_over,"note":"Stages distinguish gamut conversion, configured mapping and encoded bounds. Linear above1 is not necessarily illegal HDR. PQ encoding bounds negatives and >10000 declared nits. RGB range audit is not YUV legal-range, broadcast compliance, HDR certification or a recommended creative change."}))}
